// work.visit.record — E5 AC3 / SOP-DEL-03 §4, §5.1: the same-day visit record with its action items.
// Generated by `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor, countRows } from '@ocs/testing';
import { Forbidden, NotFound, RuleViolation, ValidationFailed } from '../../kernel/index.ts';
import { recordVisit } from '../commands/record-visit.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const pm = aStaffActor({ roles: ['pm'] });
const finance = aStaffActor({ roles: ['finance'] });
const today = new Date().toISOString().slice(0, 10);
let w: WorkWorld;
const input = (more: Record<string, unknown> = {}) => ({
  siteId: w.siteId,
  type: 'technical_inspection',
  visitDate: today,
  attendees: [
    { name: 'Person A', side: 'vv' },
    { name: 'Person B', side: 'client' },
    { name: 'Installer lead', side: 'third_party' },
  ],
  summary: 'Checked coverage after the switch upgrade.',
  decided: [{ text: 'Remaining zones checked next visit', agreedWith: 'Person B' }],
  discussed: ['Extra sensor for the loading bay — passed to Sales'],
  coverage: { done: 6, total: 20, gap: 'No access to the top floor' },
  actions: [
    { title: 'Send the fibre spec', owner: { userId: pm.id }, due: '2026-11-06' },
    { title: 'Arrange top-floor access', owner: { name: 'Person B' }, due: '2026-11-09' },
  ],
  minutesRef: 'DingTalk Action Record link',
  ...more,
});
const events = (type: string) => countRows(w.testDb.url, 'outbox WHERE event_type = $1', [type]);

beforeAll(async () => {
  w = await openWorkWorld();
  w.t.grant(pm, recordVisit.permission);
});

afterAll(async () => {
  await w.close();
});

describe('work.visit.record', () => {
  it('refuses an actor without the permission', async () => {
    await expect(w.t.kernel.execute(recordVisit, finance, input(), 'test')).rejects.toBeInstanceOf(Forbidden);
  });

  it('needs attendees, a summary, a known type, coverage X ≤ Y and the reason for a shortfall', async () => {
    for (const bad of [
      { attendees: [] },
      { summary: ' ' },
      { type: 'party' },
      { coverage: { done: 21, total: 20, gap: 'x' } },
      { coverage: { done: 6, total: 20 } },
      { decided: [{ text: 'Agreed', agreedWith: '' }] },
      { actions: [{ title: 'No owner', due: '2026-11-06' }] },
    ]) {
      await expect(w.t.kernel.execute(recordVisit, pm, input(bad), 'test')).rejects.toBeInstanceOf(
        ValidationFailed,
      );
    }
  });

  it('refuses a visit dated in the future and an unknown project', async () => {
    await expect(
      w.t.kernel.execute(recordVisit, pm, input({ visitDate: '2099-01-01' }), 'test'),
    ).rejects.toBeInstanceOf(RuleViolation);
    await expect(
      w.t.kernel.execute(recordVisit, pm, input({ siteId: randomUUID() }), 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });

  it('stores the record and its action items, each with an owner and a date, linked to the visit', async () => {
    const { id, actionIds } = await w.t.kernel.execute(recordVisit, pm, input(), 'test');
    expect(actionIds).toHaveLength(2);
    expect(
      await countRows(w.testDb.url, `visit WHERE id = $1 AND coverage_done = 6 AND coverage_total = 20`, [
        id,
      ]),
    ).toBe(1);
    expect(
      await countRows(w.testDb.url, `action WHERE visit_id = $1 AND source_kind = 'visit' AND site_id = $2`, [
        id,
        w.siteId,
      ]),
    ).toBe(2);
    expect(await events('work.visit.recorded')).toBe(1);
    expect(await events('work.visit.escalated')).toBe(0);
  });

  it('a full-coverage visit needs no gap; an escalation is flagged the same day (§7)', async () => {
    await w.t.kernel.execute(
      recordVisit,
      pm,
      input({ coverage: { done: 20, total: 20 }, actions: [], escalate: true }),
      'test',
    );
    expect(await events('work.visit.escalated')).toBe(1);
  });
});
